-- Replace membership triggers only. Keep existing membership rows and indexes.
-- Reconcile changed membership as a set; a reordered array changes no edges.

DROP TRIGGER IF EXISTS cf_chat_members_1_insert;
CREATE TRIGGER IF NOT EXISTS cf_chat_members_1_insert AFTER INSERT ON friendbook_cf_firestore_documents
WHEN NEW.parent_path='chats' BEGIN
  INSERT INTO friendbook_cf_chat_participants SELECT j.value, NEW.path, 1 FROM json_each(json_quote(json_extract(NEW.document_json,'$.participants'))) j WHERE NEW.parent_path='chats' AND json_type(json_quote(json_extract(NEW.document_json,'$.participants')))='array' AND typeof(j.value)='text' AND j.value<>'' ON CONFLICT(participant_uid,chat_path,source) DO NOTHING;
END;

DROP TRIGGER IF EXISTS cf_chat_members_1_update;
CREATE TRIGGER IF NOT EXISTS cf_chat_members_1_update AFTER UPDATE ON friendbook_cf_firestore_documents
WHEN (OLD.parent_path='chats' OR NEW.parent_path='chats')
  AND (OLD.parent_path IS NOT NEW.parent_path OR OLD.path IS NOT NEW.path
       OR json_extract(OLD.document_json,'$.participants') IS NOT json_extract(NEW.document_json,'$.participants')) AND NOT (CASE WHEN OLD.path=NEW.path AND OLD.parent_path='chats' AND NEW.parent_path='chats' AND json_type(OLD.document_json,'$.participants')='array' AND json_type(NEW.document_json,'$.participants')='array' AND json_array_length(OLD.document_json,'$.participants')=2 AND json_array_length(NEW.document_json,'$.participants')=2 AND json_type(NEW.document_json,'$.participants[0]')='text' AND json_type(NEW.document_json,'$.participants[1]')='text' AND json_extract(NEW.document_json,'$.participants[0]')<>'' AND json_extract(NEW.document_json,'$.participants[1]')<>'' AND json_extract(NEW.document_json,'$.participants[0]')<>json_extract(NEW.document_json,'$.participants[1]') AND json_extract(OLD.document_json,'$.participants[0]')=json_extract(NEW.document_json,'$.participants[1]') AND json_extract(OLD.document_json,'$.participants[1]')=json_extract(NEW.document_json,'$.participants[0]') AND EXISTS (SELECT 1 FROM friendbook_cf_chat_participants WHERE chat_path=NEW.path AND source=1 AND participant_uid=json_extract(NEW.document_json,'$.participants[0]')) AND EXISTS (SELECT 1 FROM friendbook_cf_chat_participants WHERE chat_path=NEW.path AND source=1 AND participant_uid=json_extract(NEW.document_json,'$.participants[1]')) AND NOT EXISTS (SELECT 1 FROM friendbook_cf_chat_participants WHERE chat_path=NEW.path AND source=1 AND participant_uid NOT IN (json_extract(NEW.document_json,'$.participants[0]'),json_extract(NEW.document_json,'$.participants[1]'))) THEN 1 ELSE 0 END) BEGIN
  DELETE FROM friendbook_cf_chat_participants WHERE chat_path=OLD.path AND source=1 AND (OLD.path IS NOT NEW.path OR NEW.parent_path<>'chats' OR participant_uid NOT IN (SELECT j.value FROM json_each(json_quote(json_extract(NEW.document_json,'$.participants'))) j WHERE json_type(json_quote(json_extract(NEW.document_json,'$.participants')))='array' AND typeof(j.value)='text' AND (j.value)<>''));
  INSERT INTO friendbook_cf_chat_participants SELECT j.value, NEW.path, 1 FROM json_each(json_quote(json_extract(NEW.document_json,'$.participants'))) j WHERE NEW.parent_path='chats' AND json_type(json_quote(json_extract(NEW.document_json,'$.participants')))='array' AND typeof(j.value)='text' AND j.value<>'' ON CONFLICT(participant_uid,chat_path,source) DO NOTHING;
END;

DROP TRIGGER IF EXISTS cf_chat_members_0_insert;
CREATE TRIGGER IF NOT EXISTS cf_chat_members_0_insert AFTER INSERT ON friendbook_cf_documents
WHEN NEW.collection='chats' BEGIN
  INSERT INTO friendbook_cf_chat_participants SELECT CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN (CASE WHEN j.type='object' THEN json_extract(j.value,'$.stringValue') END) ELSE j.value END, NEW.path, 0 FROM json_each(json_quote(CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN json_extract(NEW.document_json,'$.fields.participants.arrayValue.values') ELSE json_extract(NEW.document_json,'$.participants') END)) j WHERE NEW.collection='chats' AND json_type(json_quote(CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN json_extract(NEW.document_json,'$.fields.participants.arrayValue.values') ELSE json_extract(NEW.document_json,'$.participants') END))='array' AND typeof(CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN (CASE WHEN j.type='object' THEN json_extract(j.value,'$.stringValue') END) ELSE j.value END)='text' AND CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN (CASE WHEN j.type='object' THEN json_extract(j.value,'$.stringValue') END) ELSE j.value END<>'' ON CONFLICT(participant_uid,chat_path,source) DO NOTHING;
END;

DROP TRIGGER IF EXISTS cf_chat_members_0_update;
CREATE TRIGGER IF NOT EXISTS cf_chat_members_0_update AFTER UPDATE ON friendbook_cf_documents
WHEN (OLD.collection='chats' OR NEW.collection='chats')
  AND (OLD.collection IS NOT NEW.collection OR OLD.path IS NOT NEW.path
       OR (CASE WHEN json_type(OLD.document_json,'$.fields')='object' THEN json_extract(OLD.document_json,'$.fields.participants.arrayValue.values') ELSE json_extract(OLD.document_json,'$.participants') END) IS NOT (CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN json_extract(NEW.document_json,'$.fields.participants.arrayValue.values') ELSE json_extract(NEW.document_json,'$.participants') END)) AND NOT (CASE WHEN OLD.path=NEW.path AND OLD.collection='chats' AND NEW.collection='chats' AND json_type(OLD.document_json,'$.fields') IS NOT 'object' AND json_type(NEW.document_json,'$.fields') IS NOT 'object' AND json_type(OLD.document_json,'$.participants')='array' AND json_type(NEW.document_json,'$.participants')='array' AND json_array_length(OLD.document_json,'$.participants')=2 AND json_array_length(NEW.document_json,'$.participants')=2 AND json_type(NEW.document_json,'$.participants[0]')='text' AND json_type(NEW.document_json,'$.participants[1]')='text' AND json_extract(NEW.document_json,'$.participants[0]')<>'' AND json_extract(NEW.document_json,'$.participants[1]')<>'' AND json_extract(NEW.document_json,'$.participants[0]')<>json_extract(NEW.document_json,'$.participants[1]') AND json_extract(OLD.document_json,'$.participants[0]')=json_extract(NEW.document_json,'$.participants[1]') AND json_extract(OLD.document_json,'$.participants[1]')=json_extract(NEW.document_json,'$.participants[0]') AND EXISTS (SELECT 1 FROM friendbook_cf_chat_participants WHERE chat_path=NEW.path AND source=0 AND participant_uid=json_extract(NEW.document_json,'$.participants[0]')) AND EXISTS (SELECT 1 FROM friendbook_cf_chat_participants WHERE chat_path=NEW.path AND source=0 AND participant_uid=json_extract(NEW.document_json,'$.participants[1]')) AND NOT EXISTS (SELECT 1 FROM friendbook_cf_chat_participants WHERE chat_path=NEW.path AND source=0 AND participant_uid NOT IN (json_extract(NEW.document_json,'$.participants[0]'),json_extract(NEW.document_json,'$.participants[1]'))) THEN 1 ELSE 0 END) BEGIN
  DELETE FROM friendbook_cf_chat_participants WHERE chat_path=OLD.path AND source=0 AND (OLD.path IS NOT NEW.path OR NEW.collection<>'chats' OR participant_uid NOT IN (SELECT CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN (CASE WHEN j.type='object' THEN json_extract(j.value,'$.stringValue') END) ELSE j.value END FROM json_each(json_quote(CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN json_extract(NEW.document_json,'$.fields.participants.arrayValue.values') ELSE json_extract(NEW.document_json,'$.participants') END)) j WHERE json_type(json_quote(CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN json_extract(NEW.document_json,'$.fields.participants.arrayValue.values') ELSE json_extract(NEW.document_json,'$.participants') END))='array' AND typeof(CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN (CASE WHEN j.type='object' THEN json_extract(j.value,'$.stringValue') END) ELSE j.value END)='text' AND (CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN (CASE WHEN j.type='object' THEN json_extract(j.value,'$.stringValue') END) ELSE j.value END)<>''));
  INSERT INTO friendbook_cf_chat_participants SELECT CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN (CASE WHEN j.type='object' THEN json_extract(j.value,'$.stringValue') END) ELSE j.value END, NEW.path, 0 FROM json_each(json_quote(CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN json_extract(NEW.document_json,'$.fields.participants.arrayValue.values') ELSE json_extract(NEW.document_json,'$.participants') END)) j WHERE NEW.collection='chats' AND json_type(json_quote(CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN json_extract(NEW.document_json,'$.fields.participants.arrayValue.values') ELSE json_extract(NEW.document_json,'$.participants') END))='array' AND typeof(CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN (CASE WHEN j.type='object' THEN json_extract(j.value,'$.stringValue') END) ELSE j.value END)='text' AND CASE WHEN json_type(NEW.document_json,'$.fields')='object' THEN (CASE WHEN j.type='object' THEN json_extract(j.value,'$.stringValue') END) ELSE j.value END<>'' ON CONFLICT(participant_uid,chat_path,source) DO NOTHING;
END;
